DROP TRIGGER IF EXISTS guard_submission ON public.submissions;
DROP TRIGGER IF EXISTS touch_campaign ON public.campaigns;
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(display_name) ON public.profiles TO authenticated;
ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS clippza_profile_name;
ALTER TABLE public.profiles ADD CONSTRAINT clippza_profile_name CHECK(length(display_name)<=60);
CREATE OR REPLACE FUNCTION public.valid_public_link(value text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ DECLARE host text; BEGIN IF value IS NULL THEN RETURN true; END IF; IF value !~* '^https?://[^[:space:]/?#]+([/?#][^[:space:]]*)?$' THEN RETURN false; END IF; host:=lower(split_part(regexp_replace(value,'^https?://','','i'),'/',1)); host:=split_part(split_part(host,'?',1),'#',1); IF host LIKE '%@%' OR host NOT LIKE '%.%' OR host ~ '^(127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2[0-9]|3[01])\.)' OR host ~ '\.local(:[0-9]+)?$' THEN RETURN false; END IF; RETURN true; END $$;
ALTER TABLE public.campaigns DROP CONSTRAINT IF EXISTS clippza_reference_link;
ALTER TABLE public.campaigns ADD CONSTRAINT clippza_reference_link CHECK(public.valid_public_link(reference_url) AND length(coalesce(reference_url,''))<=500);
ALTER TABLE public.submissions DROP CONSTRAINT IF EXISTS clippza_clip_link;
ALTER TABLE public.submissions ADD CONSTRAINT clippza_clip_link CHECK(public.valid_public_link(clip_url));
GRANT EXECUTE ON FUNCTION public.valid_public_link(text) TO authenticated,service_role;